package connect
import "context"
// ServeProviderBatch runs independent client requests; jobs own no shared mutable state and must honor ctx. Every result is retained in input order.
func ServeProviderBatch(ctx context.Context, jobs []func(context.Context) error) []error { results := make([]error, len(jobs)); for i, job := range jobs { results[i] = job(ctx) }; return results }

cases.source_after:
package connect
import ("context"; "sync")
// ServeProviderBatch runs independent client requests; jobs own no shared mutable state and must honor ctx. Every result is retained in input order.
func ServeProviderBatch(ctx context.Context, jobs []func(context.Context) error) []error { results := make([]error, len(jobs)); for start := 0; start < len(jobs); start += 4 { var workers sync.WaitGroup; for i := start; i < min(start+4,len(jobs)); i++ { workers.Go(func() { results[i] = jobs[i](ctx) }) }; workers.Wait() }; return results }

